// TypeScript mirror of server/pulselens/models.py and config.yaml (both generated by `make types`),
// plus unions of the WebSocket messages, which the generator does not emit.
import type { DoneMessage, Heartbeat, PromptMessage, PulseAck, PulseMessage, StageDone, StageMessage } from "./models.gen";

export * from "./config.gen";
export * from "./models.gen";

/** Server to capture device (customer or lab role) on /ws/session/{id}. */
export type CaptureServerMessage = StageMessage | PromptMessage | PulseMessage | DoneMessage;
/** Capture device to server. */
export type CaptureClientMessage = PulseAck | StageDone | Heartbeat;
